package com.ship2ship.core.files

import org.springframework.beans.factory.annotation.Value
import org.springframework.stereotype.Component
import java.io.InputStream
import java.nio.file.AtomicMoveNotSupportedException
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.StandardCopyOption

/**
 * Where file bytes are kept. Keys are generated by the server (never taken from user input). Spring is the only client
 * of the store; browsers download through short-lived tokens (TR-API-02). Committed files are never deleted through the API.
 */
interface FileStore {
    /** Moves the finished temporary file into the store under [key]. */
    fun put(key: String, source: Path)

    fun open(key: String): InputStream

    fun delete(key: String)
}

/**
 * Local-disk store for development and until the FTP server details arrive (K7); an FTP(S)/SFTP implementation will
 * replace it behind the same interface. Encryption at rest is still to be decided (K7): use an encrypted volume.
 */
@Component
class LocalDiskFileStore(@Value("\${ship2ship.files.root}") root: String) : FileStore {

    private val root: Path = Path.of(root).toAbsolutePath().normalize().also { Files.createDirectories(it) }

    override fun put(key: String, source: Path) {
        val target = resolve(key)
        Files.createDirectories(target.parent)
        try {
            Files.move(source, target, StandardCopyOption.ATOMIC_MOVE)
        } catch (ex: AtomicMoveNotSupportedException) {
            // Temp folder and store on different volumes (e.g. a mounted volume in Docker).
            Files.move(source, target)
        }
    }

    override fun open(key: String): InputStream = Files.newInputStream(resolve(key))

    override fun delete(key: String) { Files.deleteIfExists(resolve(key)) }

    private fun resolve(key: String): Path {
        val path = root.resolve(key).normalize()
        require(path.startsWith(root)) { "Storage key escapes the file store" }
        return path
    }
}
